        except Exception as e:
            print(e)

    def download_file():
        try:
            s3.download_file(bucket_name, file_name, file_name)
            print(f'File {file_name} downloaded successfully')
        except Exception as e:
            print(e)

    def list_files():
        try:
            bucket = s3.Bucket(bucket_name)
            for file in bucket.objects.all():
                print(file.key)
        except Exception as e:
            print(e)

    create_bucket()
    upload_file()
    list_files()
    download_file()
